<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Media; use App\Services\ImageUploadService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class MediaController extends Controller { public function index(){return view('admin.media.index',['media'=>Media::latest()->paginate(36)]);} public function store(Request $r,ImageUploadService $images){$r->validate(['file'=>'required|image|max:8192','alt_text'=>'nullable|string|max:255']);$u=$images->store($r->file('file'),'media');$u['user_id']=$r->user()->id;$u['alt_text']=$r->alt_text;Media::create($u);return back()->with('ok','Image uploaded.');} public function destroy(Media $medium){Storage::disk($medium->disk)->delete($medium->path);$medium->delete();return back()->with('ok','Image deleted.');} }
